// Two functions that differ only in whether their pointers may alias. With
// `&mut`, the compiler may assume `a` and `b` never alias, so it can return
// the constant 16 instead of reading `*a` again.
//
// The assembly of both functions is generated by ../../../generate.sh. The
// `no_mangle` attributes keep each function as a separate, readably named
// symbol in that assembly; they sit outside the thesis snippets.

#![allow(dead_code)]
// The thesis shows the raw pointer dereferences without an `unsafe {}` block.
#![allow(unsafe_op_in_unsafe_fn)]

#[unsafe(no_mangle)]
// THESIS-SNIPPET: aliasing
unsafe fn aliasing_foo(
	a: *mut i8,
	b: *mut i8
) -> i8 {
	*a = 16;
	*b = 17;
	return *a;
}
// THESIS-SNIPPET-END: aliasing

#[unsafe(no_mangle)]
// THESIS-SNIPPET: non_aliasing
fn non_aliasing_foo(
	a: &mut i8,
	b: &mut i8
) -> i8 {
	*a = 16;
	*b = 17;
	return *a;
}
// THESIS-SNIPPET-END: non_aliasing

fn main() {}
